),existing as (select c.*,coalesce(to_jsonb(c)->>'specification','') spec, to_jsonb(c)->>'category' existing_category,to_jsonb(c)->>'item_code' existing_code from public.consumables c where to_jsonb(c)->>'archived_at' is null)
select count(*) total_source_skus,
 count(*) filter(where exists(select 1 from existing e where (lower(regexp_replace(btrim(coalesce(e.name,'')),'\s+',' ','g'))=lower(regexp_replace(btrim(coalesce(s.name,'')),'\s+',' ','g')) and lower(regexp_replace(btrim(coalesce(e.spec,'')),'\s+',' ','g'))=lower(regexp_replace(btrim(coalesce(s.specification,'')),'\s+',' ','g')) and case lower(regexp_replace(btrim(coalesce(e.unit,'')),'\s+',' ','g')) when 'pieces' then 'pcs' when 'piece' then 'pcs' when 'pc' then 'pcs' when 'rolls' then 'roll' when 'sheets' then 'sheet' when 'tubes' then 'tube' when 'boxes' then 'box' when 'packs' then 'pack' when 'bottles' then 'bottle' when 'bundles' then 'bundle' when 'kilograms' then 'kg' when 'kilogram' then 'kg' else lower(regexp_replace(btrim(coalesce(e.unit,'')),'\s+',' ','g')) end=case lower(regexp_replace(btrim(coalesce(s.unit,'')),'\s+',' ','g')) when 'pieces' then 'pcs' when 'piece' then 'pcs' when 'pc' then 'pcs' when 'rolls' then 'roll' when 'sheets' then 'sheet' when 'tubes' then 'tube' when 'boxes' then 'box' when 'packs' then 'pack' when 'bottles' then 'bottle' when 'bundles' then 'bundle' when 'kilograms' then 'kg' when 'kilogram' then 'kg' else lower(regexp_replace(btrim(coalesce(s.unit,'')),'\s+',' ','g')) end))) exact_existing_matches,
 count(*) filter(where not exists(select 1 from existing e where (lower(regexp_replace(btrim(coalesce(e.name,'')),'\s+',' ','g'))=lower(regexp_replace(btrim(coalesce(s.name,'')),'\s+',' ','g')) and lower(regexp_replace(btrim(coalesce(e.spec,'')),'\s+',' ','g'))=lower(regexp_replace(btrim(coalesce(s.specification,'')),'\s+',' ','g')) and case lower(regexp_replace(btrim(coalesce(e.unit,'')),'\s+',' ','g')) when 'pieces' then 'pcs' when 'piece' then 'pcs' when 'pc' then 'pcs' when 'rolls' then 'roll' when 'sheets' then 'sheet' when 'tubes' then 'tube' when 'boxes' then 'box' when 'packs' then 'pack' when 'bottles' then 'bottle' when 'bundles' then 'bundle' when 'kilograms' then 'kg' when 'kilogram' then 'kg' else lower(regexp_replace(btrim(coalesce(e.unit,'')),'\s+',' ','g')) end=case lower(regexp_replace(btrim(coalesce(s.unit,'')),'\s+',' ','g')) when 'pieces' then 'pcs' when 'piece' then 'pcs' when 'pc' then 'pcs' when 'rolls' then 'roll' when 'sheets' then 'sheet' when 'tubes' then 'tube' when 'boxes' then 'box' when 'packs' then 'pack' when 'bottles' then 'bottle' when 'bundles' then 'bundle' when 'kilograms' then 'kg' when 'kilogram' then 'kg' else lower(regexp_replace(btrim(coalesce(s.unit,'')),'\s+',' ','g')) end))) proposed_inserts_before_review,
 count(*) filter(where exists(select 1 from existing e where (lower(regexp_replace(btrim(coalesce(e.name,'')),'\s+',' ','g'))=lower(regexp_replace(btrim(coalesce(s.name,'')),'\s+',' ','g')) or starts_with(lower(regexp_replace(btrim(coalesce(e.name,'')),'\s+',' ','g')),lower(regexp_replace(btrim(coalesce(s.name,'')),'\s+',' ','g'))||' ') or (lower(regexp_replace(btrim(coalesce(e.name,'')),'\s+',' ','g'))='cutting disc' and s.name='Metal Cutting Disc')) and (lower(regexp_replace(btrim(coalesce(e.name,'')),'\s+',' ','g'))<>lower(regexp_replace(btrim(coalesce(s.name,'')),'\s+',' ','g')) or not exists(select 1 from catalog v where v.name=s.name and lower(regexp_replace(btrim(coalesce(v.specification,'')),'\s+',' ','g'))=lower(regexp_replace(btrim(coalesce(e.spec,'')),'\s+',' ','g'))) or (lower(regexp_replace(btrim(coalesce(e.spec,'')),'\s+',' ','g'))=lower(regexp_replace(btrim(coalesce(s.specification,'')),'\s+',' ','g')) and case lower(regexp_replace(btrim(coalesce(e.unit,'')),'\s+',' ','g')) when 'pieces' then 'pcs' when 'piece' then 'pcs' when 'pc' then 'pcs' when 'rolls' then 'roll' when 'sheets' then 'sheet' when 'tubes' then 'tube' when 'boxes' then 'box' when 'packs' then 'pack' when 'bottles' then 'bottle' when 'bundles' then 'bundle' when 'kilograms' then 'kg' when 'kilogram' then 'kg' else lower(regexp_replace(btrim(coalesce(e.unit,'')),'\s+',' ','g')) end<>case lower(regexp_replace(btrim(coalesce(s.unit,'')),'\s+',' ','g')) when 'pieces' then 'pcs' when 'piece' then 'pcs' when 'pc' then 'pcs' when 'rolls' then 'roll' when 'sheets' then 'sheet' when 'tubes' then 'tube' when 'boxes' then 'box' when 'packs' then 'pack' when 'bottles' then 'bottle' when 'bundles' then 'bundle' when 'kilograms' then 'kg' when 'kilogram' then 'kg' else lower(regexp_replace(btrim(coalesce(s.unit,'')),'\s+',' ','g')) end)))) skus_needing_manual_review
 from catalog s;
-- Unclassified legacy records require an explicit admin classification; never infer a size.
select id,name,unit,current_stock,to_jsonb(c)->>'category' category,to_jsonb(c)->>'specification' specification,to_jsonb(c)->>'archived_at' archived_at from public.consumables c;
select indexname,indexdef from pg_indexes where tablename='consumables';
select count(*) items,(select count(*) from public.consumable_requests) requests,(select count(*) from public.consumable_stock_movements) movements from public.consumables;
